import { useContext, useEffect, useMemo } from "react";
import { HeaderCustomContent } from "../components/collapsedItemsControl/collapsedItemsControl";
export const useCustomMenu = (id, menuContent) => {
    const { setContent } = useContext(HeaderCustomContent);
    const menuContentMemo = useMemo(() => menuContent, [menuContent]);
    useEffect(() => {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        setContent(c => {
            if (!c) {
                return {
                    [id]: menuContentMemo
                };
            }
            return Object.assign(Object.assign({}, c), { [id]: menuContentMemo });
        });
    }, [menuContentMemo, setContent, id]);
};
